    'fc.help_body' => 'Gestiona los códigos abreviados que se marcan desde el teléfono (como <code>*78</code>): No molestar (DND), desvío de llamadas, captura de llamadas de grupo/dirigida, escucha de llamadas, inicio/cierre de sesión en colas (<code>*81&lt;queue id&gt;</code> / <code>*80&lt;queue id&gt;</code>), pausa / reanudación en cola (<code>*22&lt;break id&gt;</code> / <code>*23</code>).',
    'fc.help_body2' => 'Se puede cambiar el <strong>código</strong> de cada uno (los códigos normales deben empezar por <code>*</code>, los que llevan un parámetro variable por <code>_*</code>) y <strong>qué roles pueden usarlo</strong> (en blanco = todos). El comportamiento en sí (lo que hace) es fijo: no se pueden añadir nuevos tipos de comportamiento, solo editar estos códigos.',
