    'cdr_reports.help_body2' => 'Cada fila es una llamada: en <b>Llamante</b>, la troncal por la que entró; en <b>Marcado</b>, la ruta y, si la llamada salió de la PBX, la troncal y el número enviado; <b>Atendida por</b> es la extensión que tomó la llamada. <b>Dirección</b>: entrante, saliente, interna o troncal a troncal (entró por una troncal y salió por otra sin que la atendiera ninguna extensión de AiPBX). Expanda una fila para ver el recorrido de las llamadas transferidas. Filtre por fecha, estado, extensión, dispositivo, dirección y troncal; escuche o descargue las grabaciones.',
