    'asterisk_settings.rtp_section_title' => 'Ajustes RTP (medios)',
    'asterisk_settings.rtp_help_body' => 'Controla qué rango de puertos transporta el audio (RTP) y si Asterisk rechaza el audio que llega de un origen inesperado. Este archivo (<code>/etc/asterisk/rtp.conf</code>) lo genera ahora el panel; las modificaciones manuales en el servidor se pierden en el siguiente "Aplicar".',
    'asterisk_settings.field_rtp_start' => 'Puerto inicial RTP',
    'asterisk_settings.rtp_start_help' => 'Inicio del rango de puertos reservado para los flujos de audio. Cada llamada simultánea consume puertos de este rango.',
    'asterisk_settings.field_rtp_end' => 'Puerto final RTP',
    'asterisk_settings.rtp_end_help' => 'Fin del rango. coturn (relé TURN) usa 13479-14999: un solapamiento rompe el audio WebRTC y se rechaza al guardar.',
    'asterisk_settings.field_rtp_strict' => 'RTP estricto (strictrtp)',
    'asterisk_settings.rtp_strict_help' => 'Si está activado, Asterisk descarta en silencio el audio que llega de cualquier origen distinto de la dirección/puerto remoto aprendido (protección contra ataques). Si la PBX remota envía medios desde un puerto inesperado, esto provoca un fallo silencioso de "sin audio" sin rastro en el registro; puede desactivarse temporalmente para el diagnóstico.',
    'asterisk_settings.rtp_strict_yes' => 'Activado (recomendado)',
    'asterisk_settings.rtp_strict_no' => 'Desactivado (para diagnóstico)',
    'asterisk_settings.rtp_restart_warning' => 'El ajuste de RTP estricto surte efecto con "Aplicar". Sin embargo, un cambio del RANGO DE PUERTOS requiere un reinicio completo de Asterisk: el conjunto de puertos se asigna una sola vez al cargar el módulo.',
    'asterisk_settings.udptl_section_title' => 'Ajustes T.38 UDPTL (medios de fax)',
    'asterisk_settings.udptl_help_body' => 'Define los rangos de puertos UDP y los parámetros de corrección de errores (FEC / suma de comprobación) para los paquetes de fax T.38 (UDPTL). Este archivo (<code>/etc/asterisk/udptl.conf</code>) se gestiona de forma dinámica.',
    'asterisk_settings.field_udptl_start' => 'Puerto inicial UDPTL',
    'asterisk_settings.udptl_start_help' => 'Puerto UDP inicial para los flujos de fax T.38 (predeterminado: 4100).',
    'asterisk_settings.field_udptl_end' => 'Puerto final UDPTL',
    'asterisk_settings.udptl_end_help' => 'Puerto UDP final para los flujos de fax T.38 (predeterminado: 4999).',
