    'asterisk_settings.field_udptl_fec_span' => 'Alcance FEC',
    'trunks.field_connection_mode' => 'Modo de conexión',
    'trunks.connection_mode_ip' => 'Basado en IP (el otro extremo tiene IP estática)',
    'trunks.connection_mode_register' => 'Registro entrante (el otro extremo se registra en nosotros)',
    'trunks.connection_mode_help' => 'Basado en IP: el otro extremo se identifica por su dirección IP y su contacto se mantiene estático; es el modo recomendado para un extremo con IP fija en la misma red. Registro entrante: el otro extremo nos envía un SIP REGISTER y su dirección se aprende de ese registro. Este modo requiere usuario y contraseña; el otro extremo autentica con ellos tanto su registro como sus llamadas.',
    'trunks.connection_mode_warning' => 'Al cambiar al modo de registro se elimina el contacto estático: no podremos llamar a esa troncal HASTA que el otro extremo se registre en nosotros. Realice este cambio de forma coordinada con el ajuste de registro del otro extremo.',
