    'sound_packs.tab' => 'Paquetes de sonido de Asterisk',
    'sound_packs.title' => 'Paquetes de sonido oficiales de Asterisk',
    'sound_packs.help_title' => 'Paquetes de sonido de Asterisk',
    'sound_packs.help_body' => 'Descarga e instala los mensajes del sistema y la música en espera oficiales de Asterisk desde <code>downloads.asterisk.org</code>. Cada paquete corresponde a un idioma en un formato; Asterisk reproduce el formato que coincide con el códec de la llamada y, si no, transcodifica (g722 para G.722, ulaw/alaw para los operadores).<br>- <strong>Core:</strong> mensajes del sistema, dígitos, buzón de voz. <strong>Extra:</strong> mensajes adicionales; primero debe estar instalado el paquete core del mismo idioma.<br>- <strong>Música en espera (opsound):</strong> se instala en <code>/var/lib/asterisk/moh/opsound</code>; para reproducirla, cree una clase MOH llamada <strong>opsound</strong> en la pestaña Música en espera.<br>- <strong>Türkçe (AiPBX):</strong> los mensajes en turco propios de AiPBX (versión de GitHub, verificados con SHA256); el idioma predeterminado es el turco, por lo que quitarlos deja mudos los mensajes del sistema. Quitar un paquete elimina solo los archivos que instaló.',
