    'ms_teams.guide_title' => 'Guía de integración con Microsoft Teams',
    'ms_teams.guide_intro' => 'AiPBX puede comunicarse con Microsoft Teams en dos niveles distintos:',
    'ms_teams.guide_dr_title' => '1. Direct Routing (SBC / troncal SIP):',
    'ms_teams.guide_dr_desc' => 'Permite a los usuarios de Teams realizar y recibir llamadas internas y externas directamente desde el teclado de Teams en el escritorio o el móvil. Requiere TLS (puerto 5061), SRTP y un certificado SSL público válido (p. ej. Let\'s Encrypt).',
    'ms_teams.guide_webhook_title' => '2. Webhooks y notificaciones de canal:',
    'ms_teams.guide_webhook_desc' => 'Envía Adaptive Cards interactivas a los canales de Teams designados para llamadas perdidas, mensajes de voz, faxes entrantes y alertas del centro de llamadas. No requiere licencias de telefonía.',
    'ms_teams.guide_ps_title' => '3. Generador automático de PowerShell:',
    'ms_teams.guide_ps_desc' => 'Desde la pestaña "Guía de PowerShell", genere automáticamente con un clic comandos de PowerShell adaptados a los ajustes de su PBX para ejecutarlos en su consola de administración de Microsoft 365.',
