    'system_update.help_title' => '¿Cómo funciona la actualización?',
    'system_update.help_body' => 'La actualización primero hace una copia de seguridad de la base de datos, la configuración y la configuración de Asterisk; después instala la nueva versión y comprueba que todo funciona. Si algo falla, vuelve automáticamente a la versión anterior. Asterisk se reinicia durante la actualización: las llamadas en curso se cortan, por lo que no se inicia mientras haya llamadas activas. También puede ejecutarse en el servidor: <code>sudo aipbx-update</code>',
