    'certificates.title' => 'Certificados',
    'certificates.header_title' => 'Certificado TLS',
    'certificates.help_title' => 'Guía de certificados',
    'certificates.help_body' => 'El portal (HTTPS), WebRTC TURNS y SIP-TLS/WSS comparten un único certificado; los cambios realizados aquí se aplican a la vez a Apache, coturn y Asterisk. <b>Let\'s Encrypt</b> es gratuito y se renueva solo; el dominio debe apuntar a este servidor y el puerto 80 debe ser accesible desde Internet. Si su organización dispone de un certificado, <b>súbalo</b> (PEM o PFX); los certificados subidos no se renuevan automáticamente, así que suba uno nuevo antes de que caduque. Con un certificado <b>autofirmado</b>, los navegadores muestran una advertencia y TURNS no funciona en ellos: las llamadas WebRTC detrás de cortafuegos pueden quedarse sin audio.',
    'certificates.level_ok' => 'El certificado es válido',
