    'sidebar.item_queue_reports' => 'Centro de informes de colas',
    'queue_reports.title' => 'Centro de informes de colas',
    'queue_reports.help_title' => 'Guía de informes de colas',
    'queue_reports.help_body' => 'Cada llamada que entra en una cola se cuenta una sola vez. <b>Contestadas</b>: conectadas con un agente. <b>Perdidas</b>: quien llamaba colgó mientras esperaba o se agotó el tiempo de la cola. <b>Abandono corto</b>: colgó en menos de %d segundos; no se tiene en cuenta en el nivel de servicio. <b>Nivel de servicio</b>: llamadas contestadas dentro del objetivo, sobre el total de llamadas excepto los abandonos cortos. <b>ASA</b>: espera media de las llamadas contestadas. <b>AHT</b>: tiempo medio de conversación. <b>Tasa de respuesta</b> (agente): con qué frecuencia contestó el agente cuando la cola le hizo sonar. <b>Devolución de llamada</b>: una llamada perdida se considera resuelta si después se llamó a su número desde una extensión, o si volvió a llamar y fue contestada. Los datos proceden del registro de colas de Asterisk; el informe puede descargarse en PDF o Excel.',
