    'ai_tts.title' => 'TTS en la nube (texto a voz)',
    'ai_tts.help_title' => 'Guía de TTS en la nube',
    'ai_tts.help_body' => 'Convierte texto en voz natural con servicios en la nube (Google, Amazon Polly, Azure, ElevenLabs, OpenAI). Escuche el resultado, descárguelo como MP3 o guárdelo como <b>locución</b> con un clic: se convierte al formato de Asterisk (WAV de 8 kHz) y se añade a Sonidos y locuciones para IVR, rutas entrantes y condiciones horarias (surte efecto tras Aplicar). <b>Estos servicios son de pago</b> y facturan por carácter; cada síntesis se guarda en el historial con su número de caracteres. Las claves de acceso se obtienen en la consola de cada proveedor, se almacenan cifradas y nunca vuelven a mostrarse en la página.',
