    'ai_tts.provider_hint_google' => 'Google Cloud Console → APIs &amp; Services: habilite "Cloud Text-to-Speech API"; use una clave JSON de cuenta de servicio (IAM → Service Accounts → Keys → JSON) o una clave de API. Hasta %s caracteres por solicitud; los textos más largos se dividen.',
    'ai_tts.provider_hint_polly' => 'En AWS IAM, cree una clave de acceso para un usuario que solo tenga "polly:SynthesizeSpeech" y "polly:DescribeVoices". Hasta %s caracteres por solicitud.',
