    'push.help_title' => 'Acerca de la arquitectura de notificaciones móviles',
    'push.help_intro' => 'El softphone móvil de AI PBX tiene una <strong>arquitectura de notificaciones por capas</strong>:',
    'push.help_layer0' => '<strong>Capa 0 (sin dependencias - predeterminada):</strong> una conexión WSS persistente, un servicio en primer plano <code>specialUse</code> compatible con Android 15 y un watchdog <code>AlarmManager</code> resistente a Doze que lo reactiva. No se necesita ningún servicio externo; las llamadas llegan incluso cuando el dispositivo está inactivo o con la pantalla apagada.',
    'push.help_layer1' => '<strong>Capa 1 (opcional - Google FCM):</strong> una garantía adicional de activación en dispositivos de fabricantes con restricciones de batería agresivas (Xiaomi, Huawei...) o cuando el usuario ha cerrado la aplicación deslizándola. <em>Solo se activa cuando la extensión no tiene un registro SIP activo, por lo que las extensiones registradas no notan ningún retraso.</em>',
    'push.help_no_fcm' => 'Si no desea usar FCM, deje el proveedor en <strong>«Local (sin dependencias)»</strong>. Así la aplicación móvil no establece ningún contacto de red con Google.',
