    'mailtpl.invite_new.subject' => '[{brand}] Se ha creado su cuenta - establezca su contraseña',
    'mailtpl.invite_new.body' => '<p>Hola, {name}:</p>{mobile_section}<p>Su cuenta en la centralita <strong>{brand}</strong> está lista. Para iniciar sesión, establezca su contraseña con el botón de abajo.</p>{account_details}{reset_button}<p>Si el botón no funciona, abra este enlace: {reset_link}</p><p><em>El enlace de contraseña es válido durante 48 horas y funciona una sola vez. Si no esperaba este correo, póngase en contacto con su administrador del sistema.</em></p>',
    'mailtpl.invite.subject' => '[{brand}] Su enlace de inicio de sesión y contraseña',
    'mailtpl.invite.body' => '<p>Hola, {name}:</p>{mobile_section}<p>Aquí tiene un nuevo enlace para establecer su contraseña en <strong>{brand}</strong>.</p>{account_details}{reset_button}<p>Si el botón no funciona, abra este enlace: {reset_link}</p><p><em>El enlace de contraseña es válido durante 48 horas y funciona una sola vez. Si no lo ha solicitado, póngase en contacto con su administrador del sistema.</em></p>',
    'mailtpl.password_reset.subject' => '[{brand}] Restablezca su contraseña',
    'mailtpl.password_reset.body' => '<p>Hola, {name}:</p><p>Se ha solicitado restablecer la contraseña de su cuenta <strong>{username}</strong>.</p>{reset_button}<p>Si el botón no funciona, abra este enlace: {reset_link}</p><p><em>El enlace es válido durante 30 minutos. Si no lo ha solicitado, ignore este correo; su contraseña no cambia.</em></p>',
    'mailtpl.voicemail.subject' => 'Nuevo mensaje de voz de {caller} ({duration})',
    'mailtpl.voicemail.body' => '<p>Hola, {name}:</p><p>Tiene un nuevo mensaje de voz en el buzón <strong>{mailbox}</strong>.</p><ul><li><strong>De:</strong> {caller}</li><li><strong>Recibido:</strong> {date}</li><li><strong>Duración:</strong> {duration}</li></ul><p>Si la grabación está adjunta, puede reproducirla aquí mismo. También puede escucharla en el portal ({portal_link}) o marcando *97.</p>',
    'mailtpl.fax_received.subject' => 'Nuevo fax recibido - {department} ({did})',
    'mailtpl.fax_received.body' => '<p>Se ha recibido un nuevo fax.</p><ul><li><strong>Unidad:</strong> {department}</li><li><strong>Número de fax:</strong> {did}</li><li><strong>De:</strong> {caller}</li><li><strong>Páginas:</strong> {pages}</li><li><strong>Recibido:</strong> {date}</li></ul><p>El fax se adjunta en PDF cuando esa opción está activada. Todos los faxes están en la bandeja de entrada de fax: {portal_link}</p>',
    'mailtpl.fax_sent.subject' => 'Fax entregado a {destination} (#{fax_id})',
    'mailtpl.fax_sent.body' => '<p>Su fax se ha entregado.</p><ul><li><strong>Para:</strong> {destination}</li><li><strong>Páginas:</strong> {pages}</li><li><strong>Hora:</strong> {date}</li></ul><p>Faxes enviados: {portal_link}</p>',
    'mailtpl.fax_failed.subject' => 'Fax NO entregado a {destination} (#{fax_id})',
    'mailtpl.fax_failed.body' => '<p>No se pudo entregar su fax.</p><ul><li><strong>Para:</strong> {destination}</li><li><strong>Páginas:</strong> {pages}</li><li><strong>Hora:</strong> {date}</li><li><strong>Motivo:</strong> {error}</li></ul><p>Puede volver a enviarlo desde el portal: {portal_link}</p>',
    'mailtpl.test.subject' => 'Correo de prueba de {brand} ({date})',
