    'storage.help_title' => 'Dónde se guardan los archivos del chat',
    'storage.help_body' => '<p>Los adjuntos del chat, sus miniaturas y las imágenes de grupo se guardan por defecto en el disco del servidor (<code>/var/lib/aipbx/chat_files</code>). Con un almacenamiento compatible con S3 (AWS S3, MinIO, Wasabi, Backblaze B2, Cloudflare R2 …) van a un bucket y los archivos grandes no ocupan la PBX.</p><p>Las descargas siguen pasando por el servicio de chat, de modo que solo los participantes de un chat pueden abrir sus archivos; el bucket puede seguir siendo privado. Los archivos guardados antes del cambio se siguen sirviendo desde el disco hasta que los mueva. Los ajustes del bucket se comprueban antes de guardarlos.</p><p>Las grabaciones de llamadas, el buzón de voz y los faxes permanecen en el disco local.</p>',
