    'netsvc.help_title' => 'Servicios de red',
    'netsvc.help_body' => 'Los teléfonos de escritorio encuentran por sí solos el servidor de aprovisionamiento cuando el servidor DHCP entrega su dirección (opción 66). DHCP y TFTP se activan por separado. Con el <strong>servidor DHCP</strong> desactivado, se mantiene su propio servidor DHCP: configure allí las opciones indicadas abajo. Activado, AiPBX entrega direcciones en una interfaz o VLAN. El <strong>servidor TFTP</strong> sirve los archivos de arranque y el firmware que suba. La configuración de cada teléfono (con la contraseña SIP) se sirve siempre por HTTPS, nunca por TFTP.',
