    'web_widgets.help_body' => 'Un widget coloca un botón "Llámenos" en cualquier sitio web. Los visitantes hablan con usted desde el navegador mediante WebRTC, o dejan su número y la PBX los llama. Pegue el código de una línea en el sitio web (o en el plugin de WordPress) y pulse <strong>Aplicar</strong> después de guardar.',
